// usage: node p.mjs <file.json|-> [conc]   prints "IN -> OUT" JSON-escaped, one per line
import { execFile } from 'node:child_process';
import { readFileSync } from 'node:fs';
const EXE = '/workspace/dataset/test4_executable';
const inputs = JSON.parse(readFileSync(process.argv[2]==='-'?0:process.argv[2], 'utf8'));
const CONC = Number(process.argv[3] || 16);
const results = new Array(inputs.length);
let idx = 0;
function next(done) {
  if (idx >= inputs.length) return done();
  const i = idx++;
  execFile(EXE, ['--a', inputs[i]], { maxBuffer: 1 << 26, encoding: 'utf8' }, (err, so, se) => {
    results[i] = { out: so, err: se, rc: err ? (err.code ?? 1) : 0 };
    next(done);
  });
}
let live = Math.min(CONC, inputs.length), fin = 0;
const finish = () => { if (++fin === live) {
  for (let i=0;i<inputs.length;i++){
    const r=results[i];
    let line = JSON.stringify(inputs[i]) + '  ->  ' + JSON.stringify(r.out);
    if (r.rc) line += '   [rc='+r.rc+' err='+JSON.stringify((r.err||'').slice(-120))+']';
    console.log(line);
  }
} };
for (let k = 0; k < live; k++) next(finish);
EOF
